arcadeDataSourceItems.script:
// =====================================================================
//  CONFIGURACIÓN: solo modifique este bloque
// =====================================================================
var PORTAL_URL = 'https://portalgis.ejercito.mil.co/portal';
var ITEM_ID    = '26c3f7e3294f4d02a740f9d4ded9eb0a';
var LAYER_ID   = 1;

var CAMPO_CATEGORIA = 'HECHO_P';
var CAMPO_DIVISION  = 'DIVISION';      // campo por el que llegan los filtros

var CAMPO_FECHA = 'FECHA_HECHO';
var CAMPO_ANIO  = '';

var OPERACION  = 'CONTEO';             // 'CONTEO' o 'SUMA'
var CAMPO_SUMA = '';                   // obligatorio solo si OPERACION = 'SUMA'

var FILTRO_BASE = '1=1';

var FILAS = [
  { etiqueta: 'POSITIVOS',      valores: ['P'] },
  { etiqueta: 'NEGATIVOS',      valores: ['N'] },
  { etiqueta: 'SIN RESULTADOS', valores: ['SR'] }
];

var INCLUIR_TOTAL       = true;
var ETIQUETA_TOTAL      = 'TOTAL COMBATES';
var INCLUIR_FILA_BLANCO = true;

var ANIO_1 = 2025;
var ANIO_2 = 2026;
// =====================================================================
//  FIN DE LA CONFIGURACIÓN
// =====================================================================

var campos = [CAMPO_CATEGORIA, CAMPO_DIVISION];
if (!IsEmpty(CAMPO_ANIO)) { Push(campos, CAMPO_ANIO); } else { Push(campos, CAMPO_FECHA); }
if (OPERACION == 'SUMA' && !IsEmpty(CAMPO_SUMA)) { Push(campos, CAMPO_SUMA); }

var fs = FeatureSetByPortalItem(Portal(PORTAL_URL), ITEM_ID, LAYER_ID, campos, false);

function SqlValor(v) {
  if (TypeOf(v) == 'Number') { return Text(v); }
  return "'" + Replace(Text(v), "'", "''") + "'";
}

function WhereAnio(a) {
  if (!IsEmpty(CAMPO_ANIO)) { return CAMPO_ANIO + ' = ' + Text(a); }
  return CAMPO_FECHA + " >= DATE '" + Text(a) + "-01-01' AND " +
         CAMPO_FECHA + " < DATE '"  + Text(a + 1) + "-01-01'";
}

function WhereFila(fila) {
  var lista = '';
  for (var i in fila.valores) {
    lista += IIf(lista == '', '', ',') + SqlValor(fila.valores[i]);
  }
  return CAMPO_CATEGORIA + ' IN (' + lista + ')';
}

// Devuelve { 'DIV01': valor, 'DIV02': valor, ... }
function MedirPorDivision(where) {
  var expr = IIf(OPERACION == 'SUMA', CAMPO_SUMA, '1');
  var est  = IIf(OPERACION == 'SUMA', 'SUM', 'COUNT');
  var g = GroupBy(Filter(fs, where), [CAMPO_DIVISION], [{ name: 'VALOR', expression: expr, statistic: est }]);
  var res = {};
  for (var r in g) {
    if (!IsEmpty(r[CAMPO_DIVISION])) {
      res[Text(r[CAMPO_DIVISION])] = IIf(IsEmpty(r.VALOR), 0, r.VALOR);
    }
  }
  return res;
}

function Valor(dic, div) { return IIf(HasKey(dic, div), dic[div], 0); }

// 0 y 0 -> 0 %; 0 y >0 -> N/A; resto -> cálculo normal
function Porcentaje(a1, a2) {
  if (a1 == 0 && a2 == 0) { return 0; }
  if (a1 == 0) { return null; }
  return Round((a2 - a1) / a1 * 100, 0);
}

function Clave(n, etiqueta) { return Text(n, '00') + '|' + etiqueta; }

// Lista de divisiones
var divisiones = [];
for (var d in Distinct(Filter(fs, FILTRO_BASE), CAMPO_DIVISION)) {
  if (!IsEmpty(d[CAMPO_DIVISION])) { Push(divisiones, Text(d[CAMPO_DIVISION])); }
}

// Consultas: 2 por fila (una por año), agrupadas por división
var medidas = [];
for (var k in FILAS) {
  var base = '(' + FILTRO_BASE + ') AND (' + WhereFila(FILAS[k]) + ')';
  Push(medidas, {
    a1: MedirPorDivision(base + ' AND ' + WhereAnio(ANIO_1)),
    a2: MedirPorDivision(base + ' AND ' + WhereAnio(ANIO_2))
  });
}

var nombre1 = 'A_' + Text(ANIO_1);
var nombre2 = 'A_' + Text(ANIO_2);
var features = [];

function Agregar(div, clave, etiqueta, v1, v2) {
  var attr = { DIVISION: div, CLAVE: clave, EVENTO: etiqueta,
               DIFERENCIA: v2 - v1, PORCENTAJE: Porcentaje(v1, v2) };
  attr[nombre1] = v1;
  attr[nombre2] = v2;
  Push(features, { attributes: attr });
}

for (var x in divisiones) {
  var div = divisiones[x];
  var t1 = 0;
  var t2 = 0;
  for (var k in FILAS) {
    var v1 = Valor(medidas[k].a1, div);
    var v2 = Valor(medidas[k].a2, div);
    t1 += v1;
    t2 += v2;
    Agregar(div, Clave(k + 1, FILAS[k].etiqueta), FILAS[k].etiqueta, v1, v2);
  }
  if (INCLUIR_TOTAL)       { Agregar(div, Clave(98, ETIQUETA_TOTAL), ETIQUETA_TOTAL, t1, t2); }
  if (INCLUIR_FILA_BLANCO) { Agregar(div, Clave(99, ''), '', 0, 0); }
}

var salida = {
  fields: [
    { name: 'DIVISION',   type: 'esriFieldTypeString' },
    { name: 'CLAVE',      type: 'esriFieldTypeString' },
    { name: 'EVENTO',     type: 'esriFieldTypeString' },
    { name: nombre1,      type: 'esriFieldTypeDouble' },
    { name: nombre2,      type: 'esriFieldTypeDouble' },
    { name: 'DIFERENCIA', type: 'esriFieldTypeDouble' },
    { name: 'PORCENTAJE', type: 'esriFieldTypeDouble' }
  ],
  geometryType: '',
  features: features
};

return FeatureSet(Text(salida));

