function Col(opciones) {
  for (var i in opciones) {
    if (HasKey($datapoint, opciones[i])) { return opciones[i]; }
  }
  return opciones[0];
}

function Num(campo) {
  var v = $datapoint[campo];
  return IIf(IsEmpty(v), 0, Number(v));
}

var agrupada = !HasKey($datapoint, 'EVENTO');

var COL_EVENTO = IIf(agrupada, 'CLAVE', 'EVENTO');
var COL_2025   = Col(['SUM_A_2025', 'sum_A_2025', 'A_2025_sum', 'A_2025']);
var COL_2026   = Col(['SUM_A_2026', 'sum_A_2026', 'A_2026_sum', 'A_2026']);
var COL_DIF    = Col(['SUM_DIFERENCIA', 'sum_DIFERENCIA', 'DIFERENCIA_sum', 'DIFERENCIA']);
var COL_PCT    = Col(['SUM_PORCENTAJE', 'sum_PORCENTAJE', 'PORCENTAJE_sum', 'PORCENTAJE']);
var ETIQUETA_TOTAL = 'TOTAL COMBATES';

var etiqueta = '';
if (agrupada) {
  var partes = Split(Text($datapoint[COL_EVENTO]), '|');
  etiqueta = IIf(Count(partes) > 1, partes[1], '');
} else {
  etiqueta = IIf(IsEmpty($datapoint.EVENTO), '', $datapoint.EVENTO);
}

var blanco  = etiqueta == '';
var esTotal = etiqueta == ETIQUETA_TOTAL;

var v1  = Num(COL_2025);
var v2  = Num(COL_2026);
var dif = v2 - v1;

var pct = '';
if (v1 == 0 && v2 == 0) { pct = '0 %'; }
else if (v1 == 0)       { pct = 'N/A'; }
else                    { pct = Text(Round(dif / v1 * 100, 0)) + ' %'; }

var rojo  = IIf(dif < 0, '#C00000', '');
var fondo = IIf(esTotal, '#D9D9D9', '');

function Celda(texto, color, alin) {
  return {
    displayText: IIf(blanco, '', texto),
    textColor: color,
    backgroundColor: fondo,
    textAlign: alin,
    iconName: '',
    iconAlign: '',
    iconColor: '',
    iconOutlineColor: ''
  };
}

var cells = {};
cells[COL_EVENTO] = Celda(etiqueta, '', 'left');
cells[COL_2025]   = Celda(Text(v1, '#,##0'), '', 'center');
cells[COL_2026]   = Celda(Text(v2, '#,##0'), '', 'center');
cells[COL_DIF]    = Celda(Text(dif, '#,##0'), rojo, 'center');
cells[COL_PCT]    = Celda(pct, rojo, 'center');

return { cells: cells };

